CREATE TABLE IF NOT EXISTS policy_sets(policy_set_id TEXT NOT NULL,version TEXT NOT NULL,jurisdiction TEXT NOT NULL,status TEXT NOT NULL,approved_by TEXT,effective_from TIMESTAMPTZ NOT NULL,effective_to TIMESTAMPTZ,payload JSONB NOT NULL,PRIMARY KEY(policy_set_id,version));
CREATE TABLE IF NOT EXISTS contracts(contract_id TEXT NOT NULL,version TEXT NOT NULL,jurisdiction TEXT NOT NULL,title TEXT NOT NULL,fingerprint TEXT NOT NULL,payload JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(contract_id,version));
CREATE TABLE IF NOT EXISTS compliance_reports(report_fingerprint TEXT PRIMARY KEY,contract_id TEXT NOT NULL,contract_version TEXT NOT NULL,decision TEXT NOT NULL CHECK(decision IN('compliant','non_compliant','review_required','blocked')),risk_score INTEGER NOT NULL CHECK(risk_score BETWEEN 0 AND 100),evidence_boundary TEXT NOT NULL CHECK(evidence_boundary IN('simulated','provider_verified')),summary JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS findings(finding_id BIGSERIAL PRIMARY KEY,report_fingerprint TEXT NOT NULL REFERENCES compliance_reports(report_fingerprint),policy_set_id TEXT,policy_version TEXT,rule_id TEXT,clause_id TEXT,code TEXT NOT NULL,severity TEXT NOT NULL,evidence JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS remediation_proposals(proposal_id TEXT PRIMARY KEY,report_fingerprint TEXT NOT NULL REFERENCES compliance_reports(report_fingerprint),clause_id TEXT,status TEXT NOT NULL CHECK(status IN('draft','approved','rejected','applied')),suggested_action TEXT NOT NULL,auto_applied BOOLEAN NOT NULL DEFAULT FALSE CHECK(auto_applied=FALSE));
CREATE TABLE IF NOT EXISTS legal_reviews(review_id BIGSERIAL PRIMARY KEY,report_fingerprint TEXT NOT NULL REFERENCES compliance_reports(report_fingerprint),reviewer_id TEXT NOT NULL,reviewer_role TEXT NOT NULL,decision TEXT NOT NULL,rationale TEXT NOT NULL,audit_fingerprint TEXT NOT NULL UNIQUE,reviewed_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS audit_events(event_id BIGSERIAL PRIMARY KEY,contract_id TEXT NOT NULL,event_type TEXT NOT NULL,payload JSONB NOT NULL,event_hash TEXT NOT NULL UNIQUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
